import type { NextConfig } from "next";

import fs from "fs-extra";
import path from "path";

import "./src/env";

const getTranspilePackages = () => {
  const packageJson = fs.readJSONSync(path.resolve("package.json")) as {
    dependencies: Record<string, string>;
    devDependencies: Record<string, string>;
  };
  return [
    ...Object.keys(packageJson.dependencies).filter((dep) =>
      dep.startsWith("@purplefish-ai"),
    ),
    ...Object.keys(packageJson.devDependencies).filter((dep) =>
      dep.startsWith("@purplefish-ai"),
    ),
  ];
};

const nextConfig: NextConfig = {
  // This will create a folder at .next/standalone which
  // can then be deployed on its own without installing node_modules.
  output: process.env.BUILD_AS_STANDALONE_OUTPUT ? "standalone" : undefined,
  distDir: process.env.NODE_ENV === "development" ? ".next-dev" : ".next",
  transpilePackages: getTranspilePackages(),

  // By default, dependencies used inside Server Components and Route Handlers will automatically be bundled by Next.js.
  // If a dependency is using Node.js specific features, Next.js opts them out to force them to use native Node.js require.
  // Next.js opts out "@prisma/client" by default, but since we use custom package name, we need to opt it out manually.
  serverExternalPackages: ["@prisma/purplefish-client"],

  eslint: {
    ignoreDuringBuilds: true,
  },

  async headers() {
    return [
      {
        source: "/:path*",
        headers: [
          {
            key: "X-Frame-Options",
            value: "DENY",
          },
          {
            key: "Content-Security-Policy",
            value: "frame-ancestors 'none';",
          },
        ],
      },
    ];
  },

  /**
   * @param {{ ignoreWarnings: { module: RegExp; }[]; }} config
   * @param {{ isServer: boolean ; }} options
   */
  webpack(config, options) {
    if (options.isServer) {
      // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
      config.ignoreWarnings = [{ module: /highlight-(run\/)?node/ }];
    }

    // this custom webpack config is required for Datadog tracing to work
    const externals = [
      // required if you use native metrics
      "@datadog/native-metrics",

      // required if you use profiling
      "@datadog/pprof",

      // required if you use Datadog security features
      "@datadog/native-appsec",
      "@datadog/native-iast-taint-tracking",
      "@datadog/native-iast-rewriter",

      // required if you encounter graphql errors during the build step
      "graphql/language/visitor",
      "graphql/language/printer",
      "graphql/utilities",
    ];
    // eslint-disable-next-line @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-member-access
    config.externals.push(...externals);

    // eslint-disable-next-line @typescript-eslint/no-unsafe-return
    return config;
  },
};

export default nextConfig;

