import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

/**
 * Turbopack plugin for Prisma client resolution in monorepo
 * Handles custom Prisma client output location and ensures proper module resolution
 */
export function prismaPlugin() {
  return {
    name: 'prisma-turbopack-plugin',

    // Configure module resolution for Prisma client
    resolve: {
      alias: {
        // Map @purplefish-ai/db imports to the actual Prisma client location
        '@purplefish-ai/db': path.resolve(__dirname, '../../packages/db/src/index.ts'),
        '@purplefish-ai/db/server': path.resolve(__dirname, '../../packages/db/src/server.ts'),
        '@purplefish-ai/db/types': path.resolve(__dirname, '../../packages/db/src/types.ts'),
        // Map the custom Prisma client location
        '@prisma/purplefish-client': path.resolve(__dirname, '../../node_modules/@prisma/purplefish-client'),
      },

      // Ensure TypeScript and JavaScript files are resolved
      extensions: ['.ts', '.tsx', '.js', '.jsx', '.mjs', '.json'],

      // Configure module resolution for Node.js compatibility
      conditionNames: ['import', 'module', 'require', 'default'],
    },

    // Configure external packages that shouldn't be bundled
    serverComponentsExternalPackages: [
      '@prisma/purplefish-client',
      '@prisma/client',
      '@neondatabase/serverless',
      '@prisma/adapter-neon',
    ],

    // Ensure Prisma files are available at runtime
    webpack: (config, { isServer }) => {
      if (isServer) {
        // Locate Prisma schema and engine files
        const prismaDir = path.resolve(__dirname, '../../packages/db/prisma');
        const prismaClientDir = path.resolve(__dirname, '../../node_modules/@prisma/purplefish-client');

        // Ensure the Prisma client is generated
        if (!fs.existsSync(prismaClientDir)) {
          console.warn(
            '⚠️  Prisma client not found at expected location.',
            'Run "pnpm db:generate" to generate the Prisma client.'
          );
        }

        // Copy Prisma schema file to output if needed
        const schemaPath = path.join(prismaDir, 'schema.prisma');
        if (fs.existsSync(schemaPath)) {
          // This ensures the schema is available for runtime operations
          config.plugins = config.plugins || [];
          config.plugins.push({
            apply(compiler) {
              compiler.hooks.afterEmit.tapAsync('CopyPrismaSchema', (compilation, callback) => {
                const outputPath = compilation.outputOptions.path;
                if (outputPath) {
                  const targetDir = path.join(outputPath, '.prisma');
                  fs.mkdirSync(targetDir, { recursive: true });
                  fs.copyFileSync(schemaPath, path.join(targetDir, 'schema.prisma'));
                }
                callback();
              });
            }
          });
        }
      }

      return config;
    },
  };
}

/**
 * Helper function to ensure Prisma client is properly generated
 * This can be called during build or development initialization
 */
export async function ensurePrismaClient() {
  const prismaClientDir = path.resolve(__dirname, '../../node_modules/@prisma/purplefish-client');

  if (!fs.existsSync(prismaClientDir)) {
    console.log('🔧 Prisma client not found. Generating...');
    const { execSync } = await import('child_process');

    try {
      execSync('pnpm db:generate', {
        cwd: path.resolve(__dirname, '../..'),
        stdio: 'inherit'
      });
      console.log('✅ Prisma client generated successfully');
    } catch (error) {
      console.error('❌ Failed to generate Prisma client:', error);
      throw error;
    }
  }
}

/**
 * Get Prisma directories for validation
 */
export function getPrismaDirs() {
  return {
    schemaDir: path.resolve(__dirname, '../../packages/db/prisma'),
    clientDir: path.resolve(__dirname, '../../node_modules/@prisma/purplefish-client'),
    dbPackageDir: path.resolve(__dirname, '../../packages/db'),
  };
}

